\begin{lemma}[Global distance bound]\label{lem:distancebound}
Under {\sf (A1-5)}, let $\tau_{\adm}$ be an admissible radius $\tau$ as in Definition~\ref{def:localfeatures}, fix some $J_{\max}>0$ and let
\[
\tau_0 = \min\left\{\tau_{\adm}, 2\sqrt{\frac{v^\star}{\sigma_{\min}(H)}}, \frac{3\sigma_{\min}(H)}{2 \Lip (\nabla^2 J'_{\nu^\star})} \right\}.
\]
Then there exists $C, C'>0$ such that for all $\tau\leq \tau_0$ and  $\nu \in \Mm_+(\Theta)$ such that $J(\nu)\leq J_{\max}$, it holds 
\begin{align*}
W_\tau(\nu) \leq \frac{C}{\tau^2}(J(\nu)-J^\star)^\frac12 &&\text{and}&&\Vert \tilde b^\theta\Vert^2+\Vert s\Vert^2\leq C'(J(\nu)-J^\star). 
\end{align*}
\end{lemma}

