\begin{enumerate}
\item[] {\sf (A1)}  $\Theta$ is a compact $d$-dimensional Riemannian manifold without boundaries. The functions $\phi:\Theta\to \Ff$ and $R:\Ff\to \RR_+$ are twice Fr\'echet differentiable, with locally Lipschitz second-order derivatives, and $\nabla R$ is bounded on sublevel sets.
\end{enumerate}

Consider a smooth increasing bijection $h:\RR_+\to \RR_+$ (such as a power function $r\mapsto r^p$) and a number of particles $m \in \NN^*$. The idea behind particle gradient-based algorithms is to parameterize the unknown measure $\nu$ as $\frac1m \sum_{i=1}^m h(r_i) \delta_{\theta_i}$ and to perform gradient-based optimization on the corresponding objective
\begin{equation}\label{eq:objectivediscrete}%\tag{$\widehat \Pp^m_\lambda$}
F_{m}((r_1,\theta_1),\dots,(r_{m},\theta_m)) \coloneqq  R\left(\frac1{m} \sum_{i=1}^{m} h(r_i)\phi(\theta_i)\right) + \frac\lambda{m} \sum_{i=1}^{m} h(r_i),
\end{equation}

\begin{equation}\label{eq:metric}
\langle(\delta r_1,\delta \theta_1),(\delta r_2,\delta \theta_2) \rangle_{(r,\theta)} = \alpha(r)^{-1} \delta r_1\delta r_2 +\beta(r)^{-1}\langle \delta \theta_1,\delta\theta_2\rangle_{\theta} 
\end{equation}

\paragraph{Lifted problem in Wasserstein space.} Assume now that $h$ has at most quadratic growth, and that the metric is defined on the whole of $\Omega$. One can then see the discrete problem~\eqref{eq:objectivediscrete} as a discretization of a problem on the space $\Pp_2(\Omega)$ of probability measures on $\Omega$ with finite second moment endowed with the Wasserstein-$2$ metric given by
\begin{equation}\label{eq:liftedproblem}%\tag{$\Pp_\lambda$}
F^\star = \min_{\mu \in \Pp_2(\Omega)} F(\mu)\quad \text{where}\quad F(\mu) \coloneqq \left( \int_\Omega h(r) \phi(\theta) \d\mu(r,\theta) \right) +  \lambda \int_\Omega h(r) \d\mu(r,\theta).
\end{equation}

This point of view leads to insights on the properties of $F_m$ that are independent of $m$, which is crucial for our theoretical analysis. For a measure $\mu\in \Pp_2(\Omega)$, we define following~\cite{liero2018optimal} the \emph{homogeneous projection} operator $\h:\Pp_2(\Omega)\to \Mm_+(\Theta)$ where  $\h\mu$ is characterized by
\begin{align*}
\int_{\Theta} \varphi(\theta) \d(\h\mu)(\theta) = \int_{\Omega} h(r)\varphi(\theta)\d\mu(r,\theta)
\end{align*}

\paragraph{Wasserstein gradient flow.} It is also possible to directly study the optimization dynamics in the space $\Pp_2(\Omega)$ for the functional $F$ of Eq.~\eqref{eq:liftedproblem}. For a measure $
u \in \Mm_+(\Theta)$, consider the vector field on $\Omega$ with expression
 egin{equation*}
g_
u(r,	heta) =  ig(\alpha(r) h'(r) J'_{
u}(	heta), eta(r) h(r)
abla J'_{
u}(	heta) ig) \in \RR 	imes T_	heta \Theta.
\end{equation*}

We refer to $g_{\h \mu}$ as the Wasserstein gradient of $F$ at $\mu$ (this notation emphasizes that it only depends on $\mu$ through $\h \mu$). Gradient flows of $F_m$ are particular cases of \emph{Wasserstein gradient flows} of $F$. The latter are defined as the absolutely continuous curves $(\mu_t)_{t\geq 0}$ in $\Pp_2(\Omega)$ that satisfy
\begin{equation}\label{eq:WGF}
\partial_t \mu_t =  \div (\mu_t g_{\h\mu_t})
\end{equation}

As seen in Eq.~\eqref{eq:gradientgeneric}, the choice of the homogeneity degree and of the metric on $\Omega$ determine a specific way to combine the \emph{vertical}  and the \emph{spatial} components of the gradient (along the variable $r$ and $\theta$, respectively). From now on, we focus on what we refer to as the \emph{conic case}, which corresponds to the following assumption:
