\begin{lemma}[Global distance bound]\label{lem:distancebound}
Under {\sf (A1-5)}, let $\tau_{\adm}$ be an admissible radius $\tau$ as in Definition~\ref{def:localfeatures}, fix some $J_{\max}>0$ and let
\[
\tau_0 = \min\left\{\tau_{\adm}, 2\sqrt{\frac{v^\star}{\sigma_{\min}(H)}}, \frac{3\sigma_{\min}(H)}{2 \Lip (\nabla^2 J'_{\nu^\star})} \right\}.
\]
Then there exists $C, C'>0$ such that for all $\tau\leq \tau_0$ and  $\nu \in \Mm_+(\Theta)$ such that $J(\nu)\leq J_{\max}$, it holds 
\begin{align*}
W_\tau(\nu) \leq \frac{C}{\tau^2}(J(\nu)-J^\star)^\frac12 &&\text{and}&&\Vert \tilde b^\theta\Vert^2+\Vert s\Vert^2\leq C'(J(\nu)-J^\star). 
\end{align*}
\end{lemma}

\begin{proof}
For this proof, we write $f_\nu - f^\star = \delta f_0 +\delta f_b + \delta f_{\mathrm{err}}$ where
\begin{align*}
 \delta f_0 &\coloneqq  \int_{\Theta_0}\phi(\theta)\d\nu(\theta),&
 \delta f_b & \coloneqq  \sum_{i=1}^m r_i \bar\nabla \phi(\theta_i) b_{i},&
\delta f_{\mathrm{err}} &\coloneqq \sum_{i=1}^{m} \int_{\Theta_i} M_{\phi,2}(\theta_i,\theta)\d\nu(\theta).
\end{align*}
where the decomposition follows from Lemma~\ref{lem:expansion}.
%
The expression for the norm of the gradient is as follows:
\[
\Vert g_\nu\Vert^2_{L^2(\nu)} = \int_{\Theta}\Vert\bar \nabla J'_\nu(\theta) \Vert^2\d\nu(\theta)
\]
where $\bar \nabla J = (2J,\nabla J)$. We start with the following decomposition for $\theta \in \Theta_i$ (recall that $J'_\nu(\theta) =\langle \phi(\theta),\nabla R(\int \phi \d\nu)\rangle +\lambda$):
\begin{multline*}
J'_\nu(\theta) = \lambda + \left\langle \phi(\theta_i) + (\theta-\theta_i)^\intercal \nabla \phi(\theta_i) + \frac12  (\theta-\theta_i)^\intercal\nabla^2\phi(\theta_i)(\theta-\theta_i)+  M_{\phi,3}(\theta_i,\theta),\nabla R(f^\star)\right\rangle \\
+\langle \phi(\theta_i)+ (\theta-\theta_i)^\intercal \nabla \phi(\theta_i) + M_{\phi,2}(\theta_i,\theta),f_\mu-f^\star\rangle_{\star}+ \langle \phi(\theta),M_{\nabla R,2}(f^\star,f)\rangle
\end{multline*}
Here we use the notation $\langle\cdot,\cdot\rangle_\star$ to denote the quadratic form associated to $\nabla^2 R(f^\star)$.
Thanks to the optimality conditions  $\bar \nabla J'_{\nu^\star}(\theta_i)=0$ for $i\in \{1,\dots,m\}$, we get
\begin{align*}
\bar \nabla_j J'_\nu(\theta) &=  [H_i(\theta-\theta_i)]_j + \langle \bar \nabla_j \phi(\theta_i),\delta f_0+\delta f_b \rangle_\star + [N(\theta_i,\theta)]_j\\
 &=  [H_i(\theta-\bar \theta_i)]_j+ \left( [H_i(\bar \theta_i-\theta_i)]_j+ \langle \bar \nabla_j \phi(\theta_i),\delta f_b \rangle_\star\right) + \langle \bar \nabla_j  \phi(\theta_i),\delta f_0\rangle_\star + [N(\theta_i,\theta)]_j
\end{align*}
where $N$ collects the higher order terms and is defined as
\begin{multline*}
 [N(\theta_i,\theta)]_j =  \langle \bar \nabla_j M_{\phi,3}(\theta_i,\theta),\nabla R(f^\star)\rangle %+ \langle \partial_j \phi(\theta_i),N_1\rangle \\
 +\langle \bar \nabla_j M_{\phi,2}(\theta_i,\theta),f-f^\star\rangle_{\star} + \langle \bar \nabla_j \phi(\theta),M_{\nabla R,2}(f^\star,f)\rangle
\end{multline*}
where $\Vert \bar \nabla_j M_{\phi,3}(\theta_i,\theta)\Vert = O(\Vert \theta-\theta_i\Vert^2)$ if $j>0$ and $O(\Vert \theta -\theta_i\Vert^3)$ if $j=0$.
Expanding the square gives the following ten terms:
\begin{align}
\int_{\Omega\setminus \Omega_0} \Vert\bar \nabla J'_\nu \Vert^2\d\nu(\theta)
&= \sum_{i=1}^{m} \int_{\Theta_i} \sum_{j=0}^{d} [H_i(\theta-\bar \theta_i)]_j^2 \d\nu \tag{I} \\
&+ \sum_{i=1}^{m}\int_{\Theta_i} \sum_{j=0}^d \left( \langle\bar \nabla_j\phi(\theta_i),\delta f_b \rangle_\star + [H_i(\bar \theta_i-\theta_i)]_j \right)^2 \d\nu(\theta) \tag{II} \\
&+ \sum_{i=1}^{m} \int_{\Theta_i} \sum_{j=0}^d \langle \bar \nabla_j\phi(\theta_i), \delta f_0 \rangle_\star^2\d\nu(\theta)  \tag{III} \\
&+ \sum_{i=1}^{m}\int_{\Theta_i} \!\! 2 \sum_{j=0}^d  [H_i(\theta-\bar \theta_i)]_j\cdot ( \langle\bar \nabla_j \phi(\theta_i),\delta f_b\rangle_\star + [H_i(\bar \theta_i-\theta_i)]_j) \d\nu(\theta) \tag{IV} \\
&+ \sum_{i=1}^{m}\int_{\Theta_i} \!\! 2 \sum_{j=0}^d [H_i(\theta-\bar \theta_i)]_j\cdot \langle \bar \nabla_j\phi(\theta_i), \delta f_0\rangle_\star\d\nu(\theta) \tag{V}\\
&+ \sum_{i=1}^{m}\int_{\Theta_i} \!\! 2 \sum_{j=0}^d (\langle\bar \nabla_j \phi(\theta_i),\delta f_b\rangle_\star + [H_i(\bar \theta_i-\theta_i)]_j)\cdot \langle \bar\nabla_j \phi(\theta_i), \delta f_0\rangle_\star\d\nu(\theta)\!\! \tag{VI}\\
&+ \sum_{i=1}^{m}\int_{\Theta_i} \!\! 2 \sum_{j=0}^d [N(\theta_i,\theta)]_j\cdot  [H_i(\theta-\bar \theta_i)]_j\d\nu(\theta) \tag{VII}\\
&+ \sum_{i=1}^{m}\int_{\Theta_i} \!\! 2 \sum_{j=0}^d [N(\theta_i,\theta)]_j\cdot  (\langle\bar \nabla_j \phi(\theta_i),\delta f_b\rangle_\star + [H_i(\bar \theta_i-\theta_i)]_j)\d\nu(\theta) \tag{VIII}\\
&+\sum_{i=1}^{m}\int_{\Theta_i} \!\! 2 \sum_{j=0}^d [N(\theta_i,\theta)]_j\cdot \langle \bar \nabla_j \phi(\theta_i), \delta f_0 \rangle_\star\d\nu(\theta) \tag{IX}\\
&+ \sum_{i=1}^{m} \int_{\Theta_i} \sum_{j=0}^d [N(\theta_i,\theta)]_j^2 \d\nu(\theta) \tag{X}
\end{align}
Terms (I) to (II) are the main terms in the expansion, while the other terms are higher order. The term (I) is a local curvature term and can be expressed as $\mathrm{(I)} = \sum_{i=1}^m \bar r_i^2 \tr \Sigma_i H_i^2$. 
%
The term (II) is a global interaction term that writes
\begin{align*}
\mathrm{(II)} &=
\sum_{i=1}^m \bar r_i^2 \sum_{j=0}^d \vert \langle\bar \nabla_j\phi(\theta_i),\delta f_b\rangle_\star + [H_i(\bar \theta_i-\theta_i)]_j \vert^2 \\
&= \sum_{i=1}^m\sum_{j=0}^d \left\vert \sum_{i'=1}^m \sum_{j'=0}^d (\langle \bar r_i \bar \nabla_j\phi(\theta_i),r_{i'}\bar \nabla_{j'}\phi(\theta_{i'})\rangle_\star + \bar H_{(i,j),(i,j')})(b_{i',j'}) \right\vert^2\\
&= \Vert (\bar K + H)(b)\Vert^2
\end{align*}
where the entries of $\bar K$ and $\bar H$ differ from those of $K$ and $H$ by a factor $\bar r_i/r_i$. More precisely,
\[
[\bar K-K]_{(i,j),(i',j')} = (\bar r_i/r_i-1)K_{(i,j),(i',j')}
\]
and similarly for $\bar H- H$. Since $\vert \bar r_i/r_i-1\vert = O(\vert b^r_i\vert)$ we have $\sigma_{\max}(\bar K-K )=O(W_\tau(\nu))$. It follows, by expanding the square, that 
\[
\Vert (\bar K + \bar H)(b)\Vert^2 = \Vert (K + H)(b)\Vert^2 + O(W_\tau(\nu)^3).
\]

The remaining terms are error terms, that we estimate directly in terms of $W_\tau(\nu)$ and $\tau$. We use in particular the fact that by H\"older's inequality, $\int_{\Theta_i} \Vert \theta - \bar \theta_i\Vert\d\nu(\theta) = O(\bar r_i^2 \tr \Sigma_i^{\frac12})$. One has 
\begin{itemize}
\item $\mathrm{(III)} =O\left(\sum_{i=1}^m \bar r_i^2 \bar r_0^4 \right)= O(W_{\tau}^4(\nu))$;
\item $\mathrm{(IV)} = \mathrm{(V)} = 0$ because the integral of the terms $H_i(\theta-\bar \theta_i)$ vanishes;
%\item $\mathrm{(V)} = O(\sum \bar r_i^2 \sigma_i \bar r_0^2) = O( W_{\tau}^3)$;
\item $\mathrm{(VI)} = O\left((\sum_{i=1}^m \bar r_i^2 (\Vert b\Vert +\Vert \delta \theta_i\Vert)\cdot \bar r_0^2\right)=O(W_{\tau}^3(\nu))$;
\item $\mathrm{(VII)} = O(\tau (\Vert \tilde b^\theta\Vert^2 + \Vert s\Vert^2)) + O(W_{\tau}(\nu)^3)$;
\item $\mathrm{(VIII)} = O(W_{\tau}^3(\nu))$;
\item $\mathrm{(IX)} = O(W_{\tau}^4(\nu))$;
\item $\mathrm{(X)} = O(\tau^2(\Vert \tilde b^\theta\Vert^2+\Vert s\Vert^2))+O(W_{\tau}(\nu)^4)$.
\end{itemize}
It follows that overall, the error term is in $O(\tau (\Vert \tilde b^\theta\Vert^2+\Vert s\Vert^2)+W_{\tau}(\nu)^3)$.
There remains to lower bound the norm of the gradient over $\Theta_0$, which can be done as follows. As seen in the proof of Lemma~\ref{lem:distancebound}, if $\tau$ is small enough then $J'_{\nu^\star}(\theta)\geq \tau^2\sigma_{\min}(H)/4$ for $\theta \in \Theta_0$. Considering only the first component of the gradient, it holds
\[
\int_{\Theta_0} \Vert\bar \nabla J'_\nu(\theta) \Vert^2\d\nu(\theta) \geq \int_{\Theta_0} 4 \vert J'_\nu(\theta)\vert^2 \d\nu(\theta).
\]
Using the expansion $J'_\nu(\theta)=J'_{\nu^\star}(\theta)+\langle \phi(\theta),M_{\nabla R,1}(f^\star,f_\nu)\rangle$, we get
\[
\int_{\Theta_0} \Vert\bar \nabla J'_\nu(\theta) \Vert^2\d\nu(\theta) \geq  C \bar r_0^2 \tau^4 + O(W_\tau(\nu)^3).
\]
The result follows by collecting all the estimates above.
\end{proof}

The remaining terms are error terms, that we estimate directly in terms of $W_\tau(\nu)$ and $\tau$. We use in particular the fact that by H\"older's inequality, $\int_{\Theta_i} \Vert \theta - \bar \theta_i\Vert\d\nu(\theta) = O(\bar r_i^2 \tr \Sigma_i^{\frac12})$. One has 
\begin{itemize}
\item $\mathrm{(III)} =O\left(\sum_{i=1}^m \bar r_i^2 \bar r_0^4 \right)= O(W_{\tau}^4(\nu))$;
\item $\mathrm{(IV)} = \mathrm{(V)} = 0$ because the integral of the terms $H_i(\theta-\bar \theta_i)$ vanishes;
%\item $\mathrm{(V)} = O(\sum \bar r_i^2 \sigma_i \bar r_0^2) = O( W_{\tau}^3)$;
\item $\mathrm{(VI)} = O\left((\sum_{i=1}^m \bar r_i^2 (\Vert b\Vert +\Vert \delta \theta_i\Vert)\cdot \bar r_0^2\right)=O(W_{\tau}^3(\nu))$;
\item $\mathrm{(VII)} = O(\tau (\Vert \tilde b^\theta\Vert^2 + \Vert s\Vert^2)) + O(W_{\tau}(\nu)^3)$;
\item $\mathrm{(VIII)} = O(W_{\tau}^3(\nu))$;
\item $\mathrm{(IX)} = O(W_{\tau}^4(\nu))$;
\item $\mathrm{(X)} = O(\tau^2(\Vert \tilde b^\theta\Vert^2+\Vert s\Vert^2))+O(W_{\tau}(\nu)^4)$.
\end{itemize}
It follows that overall, the error term is in $O(\tau (\Vert \tilde b^\theta\Vert^2+\Vert s\Vert^2)+W_{\tau}(\nu)^3)$.

\begin{corollary}[Local convergence of gradient flow]\label{cor:localGF}
Under {\sf (A1-5)}, let $J_0$ and $\kappa_0$ be given by Theorem~\ref{th:gradientinequality}. Consider $(\nu_t)_{t\geq 0}$ a projected gradient flow for $J$ as in Eq.~\eqref{eq:projectedGF}. If $J(\nu_0)\leq J_0$ then 
\begin{align*}
J(\nu_t) - J^* &\leq  (J(\nu_0) - J^*) \exp(-2\kappa_0 \min\{\alpha,\beta\}  t).
\end{align*}
\end{corollary}

